public class SecureCode {
    public static void main(String[] args) {
        // Secure: Using URLDecoder with proper validation can prevent vulnerabilities
        String input = "http://example.com?param=1%20OR%201=1";
        String decodedInput = URLDecoder.decode(input, "UTF-8");
        if (decodedInput.contains("OR")) {
            System.out.println("Input contains suspicious characters");
        } else {
            System.out.println("Decoded input: " + decodedInput);
        }
    }
}
